	@Test
	void singleMemberInheritingHttpConnectionSendsApiBindingThroughRdf4jProtocol() throws IOException {
		var member = new SailRepository(new MemoryStore());
		var server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		var protocolBinding = new AtomicReference<Value>();
		server.createContext("/protocol", exchange -> {
			try (exchange) {
				byte[] version = Protocol.VERSION.getBytes(StandardCharsets.UTF_8);
				exchange.sendResponseHeaders(200, version.length);
				exchange.getResponseBody().write(version);
			}
		});
		server.createContext("/repositories/member", exchange -> evaluateHttpQuery(exchange, member, protocolBinding));
		try {
			member.init();
			server.start();
			var url = "http://127.0.0.1:" + server.getAddress().getPort();
			assertNestedValuesOwnTheirBinding(new HTTPRepository(url, "member") {
			});
			assertThat(protocolBinding).hasValue(SimpleValueFactory.getInstance().createLiteral(1));
		} finally {
			server.stop(0);
			member.shutDown();
		}
	}

	private static void evaluateHttpQuery(HttpExchange exchange, Repository member,
			AtomicReference<Value> protocolBinding)
			throws IOException {
		try (exchange; var connection = member.getConnection()) {
			String encoded = "POST".equals(exchange.getRequestMethod())
					? new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8)
					: exchange.getRequestURI().getRawQuery();
			var parameters = WWWFormCodec.parse(encoded, StandardCharsets.UTF_8);
			String sparql = parameters.stream()
					.filter(parameter -> Protocol.QUERY_PARAM_NAME.equals(parameter.getName()))
					.findFirst()
					.orElseThrow()
					.getValue();
			var query = connection.prepareTupleQuery(sparql);
			for (var parameter : parameters) {
				if (parameter.getName().startsWith(Protocol.BINDING_PREFIX)) {
					String name = parameter.getName().substring(Protocol.BINDING_PREFIX.length());
					Value value = Protocol.decodeValue(parameter.getValue(), connection.getValueFactory());
					query.setBinding(name, value);
					if ("x".equals(name)) {
						protocolBinding.set(value);
					}
				}
			}
			var format = TupleQueryResultFormat.SPARQL;
			exchange.getResponseHeaders().set("Content-Type", format.getDefaultMIMEType());
			try (var result = query.evaluate()) {
				exchange.sendResponseHeaders(200, 0);
				QueryResultIO.writeTuple(result, format, exchange.getResponseBody());
			}
		}
	}

