	private static void assertSingleMemberDelegatesLuceneQuery(Function<LuceneSail, SailRepository> createMember,
			Function<SailRepository, Endpoint> createEndpoint) {
		var vf = SimpleValueFactory.getInstance();
		IRI subject = vf.createIRI("urn:document");
		var parameter = vf.createLiteral("api");
		var lucene = new LuceneSail();
		lucene.setParameter(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		lucene.setBaseSail(new MemoryStore());
		var member = createMember.apply(lucene);
		member.init();
		FedXRepository federation = FedXFactory.newFederation()
				.withMembers(List.of(createEndpoint.apply(member)))
				.create();
		String sparql = """
				PREFIX search: <http://www.openrdf.org/contrib/lucenesail#>
				SELECT ?s WHERE {
					{ SELECT ?x WHERE { VALUES ?x { "api" } } }
					?s search:matches [ search:query "hello" ] .
				}
				""";
		try {
			federation.init();
			try (RepositoryConnection connection = member.getConnection()) {
				connection.add(subject, vf.createIRI("urn:title"), vf.createLiteral("hello"));
				var query = connection.prepareTupleQuery(sparql);
				query.setBinding("x", parameter);
				assertThat(QueryResults.asList(query.evaluate())).as("direct Lucene with API binding")
						.extracting(row -> row.getValue("s"))
						.containsExactly(subject);
			}
			try (RepositoryConnection connection = federation.getConnection()) {
				var query = connection.prepareTupleQuery(sparql);
				assertThat(QueryResults.asList(query.evaluate())).as("single-member FedX without API binding")
						.extracting(row -> row.getValue("s"))
						.containsExactly(subject);
				query.setBinding("x", parameter);
				assertThat(QueryResults.asList(query.evaluate())).as("single-member FedX with API binding")
						.extracting(row -> row.getValue("s"))
						.containsExactly(subject);
			}
		} finally {
			federation.shutDown();
			member.shutDown();
		}
	}

